export const HSK_EXTENDED_DICTIONARY: Record<string, HskExtendedEntry> = {};

for (const tuple of COMPACT_HSK_ENTRIES) {
  const [
    hanzi,
    pinyin,
    hanViet,
    meaning,
    radical,
    strokeCount,
    hskLevel,
    components,
    mnemonic,
    rawExamples,
    rawCompounds,
  ] = tuple;

  HSK_EXTENDED_DICTIONARY[hanzi] = {
    hanzi,
    pinyin,
    hanViet,
    meaning,
    radical,
    strokeCount,
    hskLevel,
    components,
    mnemonic,
    examples: (rawExamples || []).map(([sentence, py, vn]) => ({
      sentence,
      pinyin: py,
      meaning: vn,
    })),
    compoundWords: (rawCompounds || []).map(([word, py, vn]) => ({
      word,
      pinyin: py,
      meaning: vn,
    })),
  };
}
